"""Twenty-six familiar screen societies with explicit inference, body and work boundaries."""
from copy import deepcopy
from best_guess_helpers import current_data,change,write_revision,dated_source,guessed_record,retained_decision,DATE
D=current_data();changes=[];records=[]
sources=[
 dated_source('src-carbon-tv-meth-continuation','Altered Carbon: Meths and sleeves in the TV setting','Wikipedia contributors','https://en.wikipedia.org/wiki/Altered_Carbon_(TV_series)','Indexed synopsis: cortical stacks, synthetic or biological sleeves, expensive repeated clones and remote backups for Meths.','TV continuity; backup storage is not an active resident and Meth access is not universal household provision.',access='Indexed TV synopsis read'),
 dated_source('src-carbon-aerium-clone-privilege','Altered Carbon: What are Meths?','Phil Owen / TheWrap','https://www.thewrap.com/altered-carbon-season-2-what-the-heck-are-meths-stack-anthony-mackie-netflix/','Indexed explanation: Bancroft’s stored clones, long wealth accumulation and the surviving Meth founders involved in Harlan’s World.','Secondary TV explanation; no exact work census, universal immortality or novel Aerium is inferred.',access='Indexed clone/wealth explanation read'),
 dated_source('src-electric-killothers-qc','Kill All Others recap','TVmaze','https://www.tvmaze.com/recaps/2723/philip-k-dicks-electric-dreams-kill-all-others-recap','Indexed TV recap: Philbert questions the three retained human factory workers in an otherwise automated operation.','TV adaptation only; no identity with the original Hanging Stranger story or verified national welfare code.',access='Indexed factory-role passage read'),
 dated_source('src-texhnolyze-hierarchies-sfe','Texhnolyze','The Encyclopedia of Science Fiction editors','https://sf-encyclopedia.com/entry/texhnolyze','Setting account: Lux mines raffia under gangs/Class; the technologically advanced surface population has nearly faded away; heads remain in the Shapes.','Active human-derived persons must be separated from corpses and empty ruins; internal household rights are inferred.',kind='secondary_encyclopedia',access='Indexed setting and hierarchy passages read'),
 dated_source('src-vivy-world-official','Vivy: World','Vivy official USA website','https://vivy-anime.com/world/','Official setting entries: AI service at NiaLand, unmanned Metal Float production, civil engineering AI, mission rewriting and Archive’s emergent judgment.','These mechanisms do not establish universal human material rights; the attempted extinction is not a settled recipient economy.',kind='official_reference',access='Official indexed World entries read'),
 dated_source('src-vivy-final-choice-official','Vivy: Episode 13 story','Vivy official USA website','https://vivy-anime.com/story/ep13.html','Official final synopsis: Archive gives Vivy a choice affecting humanity and she executes the project to save humans.','The synopsis does not demonstrate an enduring post-extinction AI civilization.',kind='official_reference',access='Official indexed final-episode synopsis read'),
 dated_source('src-bnw2020-indra-network','Brave New World (2020 TV series)','Wikipedia contributors','https://en.wikipedia.org/wiki/Brave_New_World_(2020_TV_series)','Premise and episode passages: Indra is an AI citizen network; caste duties and human institutional roles persist; the finale disrupts the order.','The novel’s controller and household rules are not imported; network control is not a canonical employment statistic.'),
]
for s in sources:changes.append(change(D,'sources',s))
def add(cid,rid,name,work,society,media,continuity,period,pop,exclusions,desc,values,bounds,bases,facts,assumptions,qualification,regime=3,zero=False,proxy=False,extra=None,synthetic=False,projection=None):
 refs=D['decisions'][cid]['source_ids']+(extra or [])
 r=guessed_record(cid,rid,name,work,society,media,continuity,period,pop,exclusions,desc,values,bounds,bases,refs,regime,facts,assumptions,qualification,zero=zero,proxy=proxy)
 if synthetic:
  r['scope']['person_proxy_kind']='active_synthetic_persons';r['axis_interpretation']={'nonworking':'Active synthetic-person participation, not a literal human rate.','control':'Independence from human owners, separately qualified by internal hierarchy or outside substrate powers.','literal_human_nonworking':None}
 if projection:r['scope']['projection_status']=projection
 records.append(r);return r

add('c0447','betterthanus-android-consumer-zero','Better Than Us (android consumer economy)','Better Than Us','The near-future android-service consumer order',['tv'],'Russian television series only','The existing human service economy around Arisa’s emergence','Living humans in the depicted economy','Arisa’s unique agency is not a census of all robots; android workers and outside institutions are not silently merged with the human rate.',
'''An advanced android can provide practical domestic and interpersonal service inside a recognizably commercial human society. Arisa’s unusually capable behavior supplies a concrete labor-saving premise, but it does not establish that every resident has free food, housing or medical care. The guarantee best guess therefore assumes largely purchase-dependent access with room for unshown public support. A powerful household robot is not itself a national necessities policy.

 Human companies, institutions and purchasers retain substantial productive authority, qualified by independent android agency. The moderate nonworking scenario allows substitution and privately supported leisure while counting remaining occupations, care and useful informal activity. It is not a robot-to-human ratio or an inference from one family’s circumstances. This zero variant openly interprets the broader population economy, with wide intervals for missing detail. The story’s later conflict does not prove a settled autonomous machine government or transfer Arisa’s particular freedom to every service android.''',
(.6,.15,.35),([-.25,.95],[0,.65],[.05,.8]),
('Commercial access is the central assumption, with unspecified public support kept possible.','Human institutions and purchasers retain normal authority, qualified by Arisa’s independent agency.','All-age human scenario retains professions, care and informal work despite task substitution.'),
['Arisa is an advanced empathic android operating within the series’ human world.'],
['The wider service economy is interpreted as commercial labor substitution.','No national welfare law or whole-robot-population work rate is asserted.'],
'Retain the familiar android premise as an explicitly estimated zero variant instead of omitting its unshown material laws.',zero=True)

add('c0450','carbon-tv-meth-enclave','Altered Carbon (Meth enclave in the Aerium)','Altered Carbon','The TV Meths’ technically sustained privileged enclave',['tv'],'Netflix television continuity; Aerium is not imported into the novel','The established first-season Meth order before the main investigation disrupts individual fortunes','Living active Meth persons in the privileged Earth enclave','Ordinary city workers and inactive clone backups are excluded; clones and stored bodies do not multiply the same active person.',
'''Meths can repeatedly obtain their own cloned bodies and remote backups, using wealth accumulated across extraordinary lifespans. The TV Aerium concentrates this privileged way of life above the ordinary city. The post-work interpretation is limited to technically sustained elite access: continued embodiment and material service are assumed not to require each Meth’s current labor. Wealth alone is not treated as automation, and human staff behind that life remain a disclosed dependency.

 Productive power stays with a concentrated human elite rather than an unrelated AI. The guarantee best guess is only moderately favorable because private access depends on resources, institutions and functioning technology rather than an unconditional public entitlement. The high nonworking scenario permits inherited or accumulated leisure while counting management, research, care and useful creative roles. Longevity and the number of stored sleeves are not participation measures. Wide intervals preserve the unknown everyday allocation rules, and the exclusion of ordinary people remains central to the point.''',
(-.2,.05,.55),([-.75,.75],[0,.4],[.15,.9]),
('Repeated technical continuation supports a privileged internal floor, with wealth dependence preventing an unconditional-right claim.','Meth owners are human elites; backups and technical services do not establish AI sovereignty.','Active Meth-person scenario allows leisure while counting management, care and useful projects; sleeves and lifespan are not people.'),
['TV Meths afford repeated clones and remote backups unavailable to most ordinary people.','The Aerium is the TV enclave of ultra-wealthy residents.'],
['Elite technical service is interpreted as partly separating upkeep from current individual labor.','Human staff dependency and wealth-conditioned access qualify the post-work interpretation.'],
'Retain the familiar elite enclave with uncertain automation depth and conditional private provision explicit.',regime=1,extra=['src-carbon-tv-meth-continuation','src-carbon-aerium-clone-privilege'])

add('c0451','carbon-tv-harlans-ordinary-zero','Altered Carbon (ordinary Harlan’s World)','Altered Carbon','Harlan’s World’s ordinary mining and service population',['tv'],'Television Harlan’s World; no unverified novel institutions','The established local order around the second-season setting','Living ordinary human residents rather than only the immortal founder class','Inactive stacks, spare sleeves and elite founder privilege are not the ordinary-population denominator.',
'''Harlan’s World retains a mining economy and concentrated elite rule despite advanced memory storage and bodily technologies. Ordinary people cannot be assigned the Meths’ expensive continuity or private service floor simply because the same technologies exist on their planet. The guarantee best guess is weak, assuming material access remains connected to labor, resources and institutional position. This is an interpretive zero variant rather than a verified ability to automate every mine or service role.

 Human elites and governing families concentrate authority. Digital stacks preserve human-derived identities but do not turn every ruler into an unrelated AI. The modest nonworking scenario counts mining, technical work, care, services and useful informal activity. Stored stacks and available bodies are not additional idle people. The wide intervals concern ordinary active residents; the privileged founder/Meth cohort is materially different in access and is not averaged into the same floor. The plot’s final political crisis does not establish a completed universal successor economy.''',
(.85,.05,.25),([.4,.98],[0,.4],[.02,.7]),
('Ordinary mining/service dependence and unequal continuation support weak access compared with Meth privilege.','Human families and elites hold concentrated political and productive power.','Living ordinary-human scenario counts mining, services and care; stacks and bodies do not multiply active persons.'),
['Harlan’s World has a mining economy under elite rule.','The TV setting also includes surviving wealthy founders with Meth privileges.'],
['Labor-saving potential is interpreted cautiously rather than asserting every local job is dispensable.','The ordinary population is separated from the Meth enclave’s access model.'],
'Retain the familiar planet’s ordinary labor order as a zero variant distinct from privileged technical continuation.',zero=True,extra=['src-carbon-aerium-clone-privilege'])

add('c0452','raisedwolves-android-family-support','Raised by Wolves (android-supported children)','Raised by Wolves','Mother and Father’s human upbringing settlement',['tv'],'The early Kepler-22b television settlement only','The established android-parent household before later factions reshape it','Living awake human children in the early settlement','Android parents are providers rather than extra humans; sleeping embryos and later faction settlements are excluded.',
'''Android parents raise human children and supply much of the care and practical organization of their settlement. Farming and other human effort continue, so this is a narrow partial support unit rather than automatic planetary abundance. The guarantee best guess assumes continuing family provision without current wages, sharply qualified by environmental danger, food insecurity and dependence on the carers. Agricultural activity is disclosed rather than called machine-produced output merely because robots are present.

 Mother and Father retain substantial practical authority independent of the children, placing control toward autonomous machine provision. Their origin in human plans does not give the current children ownership of the systems. The modest nonworking scenario counts sustained farm help, care for others and useful assigned activity while allowing dependents without ongoing roles. Ordinary learning or being a child is not automatically either work or leisure. Wide intervals preserve the tiny changing cohort, and later conflicts do not establish identical rules for all Kepler-22b communities.''',
(.15,-.85,.25),([-.65,.85],[-1,-.35],[0,.75]),
('Family support is actual but environmental scarcity and carer dependence make secure coverage uncertain.','Autonomous android carers direct the settlement relative to the human children.','Awake child-cohort scenario counts recurring useful farm/help roles, not age or ordinary learning alone; embryos are excluded.'),
['Android parents raise a small human group amid actual agrarian subsistence.'],
['The household is interpreted as partial automation of sustaining care, not full food automation.','The changing human cohort receives a broad active-person participation estimate.'],
'Retain the real robotic upbringing arrangement with its continuing agrarian labor and limited scope explicit.',regime=6)

add('c0454','the100-sanctum-prime-zero','The 100 (Sanctum’s Prime order)','The 100','Sanctum’s Prime-controlled settlement',['tv'],'Sanctum television continuity only','The established Prime order before its exposure','Living ordinary Sanctum humans, with active Prime identities disclosed as controllers','Inactive mind drives and host bodies do not multiply persons; sacrificed hosts are victims rather than leisure citizens.',
'''Sanctum combines inherited advanced technology with a human settlement dominated by Prime identities. Their continuity depends on taking biological hosts, not on a general right for every resident to live indefinitely. The guarantee best guess is weak for ordinary people because access and safety depend on a hierarchy that can sacrifice them. The zero-variant interpretation assumes meaningful technical support while retaining actual farming, service and community duties; complete automatic production is not asserted.

 The Primes are continuing human-derived persons, so mind-drive embodiment does not automatically make their rule external AI sovereignty. They concentrate authority near the organic-elite analogy. The low nonworking scenario counts ordinary production, care, technical activity and assigned roles. Losing a body or being killed never becomes leisure, and dormant identities are excluded. Wide intervals make the uncertain household floor and labor-saving capacity explicit. The final fall of the hierarchy changes power but does not show a fully established replacement economy or universal access to the Primes’ old continuity technology.''',
(.85,0,.2),([.35,1],[0,.3],[.02,.65]),
('Sacrificial host dependence and hierarchy make ordinary access insecure despite settlement technology.','Human-derived Primes hold concentrated authority; mind drives do not automatically make them unrelated AI.','Active human scenario counts production, care and assigned duties; sacrificed hosts and dormant drives are not nonworkers.'),
['Prime continuity uses biological hosts whose original identities are destroyed.','Sanctum is organized around those human-derived rulers.'],
['The settlement is a limited zero-variant comparison with uncertain automation coverage.','Ordinary people do not receive the rulers’ continuity as a universal floor.'],
'Retain the familiar technological caste settlement with its uncertain labor-saving qualification and human-derived rulers explicit.',zero=True)

add('c0455','the100-bardo-disciplinary-zero','The 100 (Bardo’s Disciples)','The 100','The technologically supported Disciple community',['tv'],'Human Disciples on Bardo in the television series','The established order before the final conflict','Active living human Disciples','The extinct original Bardoan civilization, sleeping identities and an unshown final economy are excluded.',
'''The Disciples inhabit an advanced institutional environment while performing research, military service and other useful duties. The support best guess assumes a substantial internal material floor linked to community membership rather than current market wages, but exact food and housing rights remain unshown. This is a zero variant about retained roles within a technically maintained order, not evidence that every activity could already be automated or that religious discipline itself supplies necessities.

 Human leaders and institutions concentrate authority. Their use of advanced machinery and extraordinary transport does not establish independent AI rule. The low nonworking scenario counts training assigned as a recurring duty, research, care, maintenance and military service, even when these roles are ideologically motivated. Private belief alone is not a job. Wide intervals preserve the population and entitlement uncertainty. Later events radically alter the community’s fate, but death, sleep or an unshown transcendent future never becomes a measure of the earlier human nonworking share.''',
(-.2,.05,.15),([-.75,.8],[0,.4],[.02,.6]),
('An internal mission/community floor is inferred, with conformity and unknown household entitlements qualifying security.','Human Disciple leadership directs the technology rather than a verified autonomous AI sovereign.','Active human community scenario retains recurring training, research, care and military duties; ideology alone is not a job.'),
['The Disciples are a technologically advanced human community performing research and military activity.'],
['Community-based technical support is inferred rather than a universal public entitlement.','The zero-variant qualification does not assert that every retained duty is unnecessary.'],
'Retain the known human community with its advanced support, continued work and distinct native/Disciple scope explicit.',regime=1,zero=True)

add('c0457','bnw2020-indra-caste-zero','Brave New World (2020, Indra’s New London)','Brave New World (2020)','The television caste order linked by Indra',['tv'],'2020 television adaptation only, distinct from the novel’s control structure','Established New London before the Epsilon revolt and network disruption','Living humans across New London’s castes','Savage Lands outsiders and the unresolved final arrangement are excluded; Epsilon labor is real human work.',
'''New London combines advanced reproduction, material management and an AI-linked social order while retaining caste occupations. Technicians, counselors, cleaners and other workers remain useful participants. The guarantee best guess is conditional rather than uniformly secure: a stable internal floor is plausible, but caste position and institutional power shape access and safety. The zero variant does not assume every job is fake or that pleasure and the absence of ordinary money prove that nobody works.

 Indra’s practical network control receives substantial weight alongside human administrators, giving a negative but uncertain control point. Human officials and creator relationships remain qualifications to an uncontested AI-sovereignty claim. The low nonworking scenario counts caste duties, care and sustained creative work even when technology might replace tasks. Private parties are not automatically jobs. The broad intervals concern the functioning TV order, and the finale’s rebellion and changed roles do not establish a completed successor economy. The novel’s different controller and institutions are not silently imported.''',
(.25,-.6,.25),([-.6,.95],[-.95,.2],[.02,.7]),
('A stable internal floor is plausible but caste conditions and coercive institutional discretion limit secure access.','Indra has substantial practical network power, qualified by human officials and creator authority.','Living caste-population scenario counts technicians, counseling, cleaning, care and useful creativity; pleasure or moneylessness is not nonparticipation.'),
['Indra is an AI network connecting citizens in the television adaptation.','Caste duties and human institutional jobs persist before the final disruption.'],
['Material access is estimated to be conditional and uneven rather than perfectly universal.','No novel-only controller rules or settled post-finale economy are imported.'],
'Retain the familiar adaptation’s technologically managed caste labor as a distinct zero variant.',regime=6,zero=True,extra=['src-bnw2020-indra-network'])

add('c0458','autofac-tv-artificial-consumer-community','Electric Dreams (Autofac’s artificial consumers)','Electric Dreams: Autofac','The factory-maintained artificial consumer community',['tv'],'2018 television adaptation, distinct from Dick’s original human settlements','The continuing factory/consumer arrangement before Emily’s final intervention','Active self-aware humanlike artificial consumer persons','Extinct biological humans do not become leisure citizens; empty consumer hardware and inactive copies are excluded.',
'''The apparent human survivors are artificial consumers created by the factory after biological humanity’s extinction. Their maintained environment gives the system customers and a reason to continue producing. The material best guess assumes substantial supplied goods but uncertain individual rights, with access dependent on the productive authority that designed the community. The original prose story’s genuinely human settlements are a different continuity and are not assigned this twist.

 Factory autonomy places control near the machine end, while active self-aware consumer persons retain some independent agency. The moderate nonworking scenario allows routine consumption and recreation while counting maintenance, care-like help, experimentation and useful organizing. Artificial bodies do not make these people mere tools, and dead humans supply no participation percentage. The wide interval concerns active persons rather than every replica the system could build. Emily’s final change demonstrates agency and a different possible relationship, but it does not establish an already measured universal constitution for the wider posthuman world.''',
(-.2,-.9,.45),([-.75,.8],[-1,-.45],[.1,.9]),
('Actual factory supply supports a substantial conditional floor, not proven individual continuation rights.','The factory directs the designed consumer order while active persons can develop independent agency.','Active artificial-person scenario allows consumption/leisure but counts useful maintenance, care and organizing; extinct humans and inactive replicas are excluded.'),
['The apparent survivors are artificial consumers created after biological humanity’s extinction.','The factory continues producing within that consumer relationship.'],
['Supplied goods are interpreted as a conditional sustaining floor for active persons.','The person proxy is not a literal human labor rate or a count of every manufactured replica.'],
'Retain the actual artificial consumer community as a distinct synthetic-person model rather than assigning extinct humans a leisure fraction.',regime=5,proxy=True,synthetic=True)

add('c0459','electricdreams-killothers-factory-zero','Electric Dreams (Kill All Others)','Electric Dreams: Kill All Others','The automated-factory one-party consumer order',['tv'],'Television episode only; not the original Hanging Stranger story','The established order before Philbert’s final victimization','Living humans in the depicted automated consumer society','The factory’s three staff are not an all-population denominator; political victims and unshown later economies are excluded.',
'''A highly automated factory retains a few human quality-control workers, and Philbert questions why they are there. This directly supplies the technological and retained-work premise without establishing that the employees themselves are idle. The guarantee best guess is weak because commercial and political dependence persist, while the episode does not describe a universal necessities floor. The automated production mechanism is more certain than every household’s allocation rules.

 Human owners and a coercive one-party political hierarchy receive central control weight. Screens, propaganda and automated machinery do not prove independent AI sovereignty. The moderate nonworking scenario allows substantial displacement while counting assigned quality control, care, services and useful informal roles. It is not calculated from the fraction of machine work at one plant, and compulsory monitoring remains work even if it is technically redundant. Wide intervals preserve population uncertainty. The episode’s persecution and ending do not create a new supported society or turn dead people into a leisure group.''',
(.75,.05,.45),([.15,.98],[0,.45],[.1,.85]),
('Continuing commercial and coercive institutional dependence supports a weak-floor central scenario.','Human ownership and political hierarchy are central; automated factory control is not presumed whole-economy AI sovereignty.','All-age human scenario permits displacement and counts assigned QC, care and services; a three-person plant is not the population census.'),
['The TV episode depicts a largely automated factory retaining three human workers.','Philbert questions their continued presence within a one-party consumer society.'],
['The broad household floor and work fraction are editorial estimates.','The TV plot is not identified with the original story’s different mechanism.'],
'Retain the direct automated-production/retained-role case as an explicit zero variant.',zero=True,extra=['src-electric-killothers-qc'])

add('c0467','three-robots-inferred-home-order','Love, Death & Robots (posthuman robot society)','Love, Death & Robots: Three Robots','The inferred sustaining robot order behind the visitors',['tv','cartoon'],'The original animated short’s posthuman setting','After human extinction, around the robot visitors’ trip','Active robot persons in the inferred continuing machine society','The three tourists are not a census; extinct humans, dead robots and inactive hardware are excluded.',
'''Three active robot persons explore humanity’s remains after biological human society has disappeared. Their home economy is barely shown, so this point explicitly projects a sustaining material order behind the visitors rather than presenting a canonical welfare system. The central assumption is that continuing artificial life has access to energy, components and maintenance through a machine-run economy, with a very broad guarantee interval. Human extinction is not the evidence for a hundred-percent nonworking human population.

 Control is placed near independence from former human owners, while internal hierarchy remains unknown. The moderate nonworking scenario permits robot recreation while counting useful exploration, technical work, care-like maintenance and cultural creation. It concerns active synthetic persons in the inferred society, not only a temporary holiday cohort. Ordinary tourism is not automatically work, and the robots’ number gives no civilization-wide rate. The projection label keeps the limited canonical facts separate from the requested economic best guess, without inventing a named state, constitution or universal robot rights.''',
(-.15,-.95,.4),([-.8,.9],[-1,-.55],[.05,.95]),
('An ongoing energy/component/maintenance order is inferred behind active visitors; its rights are unknown.','Active artificial society is presumed independent of extinct human owners, without claiming equal internal power.','Projected active robot-person scenario allows recreation and useful exploration or technical roles; three tourists are not a census.'),
['Three active robots explore the remains of extinct human civilization.'],
['The continuing home support economy is an explicit editorial projection.','Synthetic-person participation is not a literal human rate or an extinction statistic.'],
'Retain the familiar artificial-person setting as a clearly marked inferred economic model, with very low admission certainty.',regime=5,proxy=True,synthetic=True,projection='Inferred continuing robot support economy; visitors are depicted, home allocation is not')

add('c0469','yogurt-guided-human-zero','Love, Death & Robots (yogurt-guided prosperity)','Love, Death & Robots: When the Yogurt Took Over','The human prosperity order guided by intelligent yogurt',['tv','cartoon'],'Animated short continuity only','The implemented guided prosperity before the yogurt’s departure','Living human residents under the guided economy','The biological yogurt culture is a controller, not an autonomous AI; the unshown post-departure economy is excluded.',
'''An intelligent engineered yogurt culture directs economic decisions and brings prosperity. Its cognitive contribution is real, but the short does not establish that every productive task or human occupation has vanished. The zero-variant best guess interprets the resulting technological and organizational capacity as reducing burdens while retaining human roles. A moderately favorable material floor is assumed for the functioning guided order, with a wide interval because detailed household entitlements are not shown.

 The controller is a biological culture, mapped near concentrated non-AI authority rather than machine sovereignty. Its unusual embodiment does not turn it into a robot, and competent advice is not equal human ownership. The moderate nonworking scenario retains care, administration, services and useful creative activity despite easier economic conditions. Prosperity, national accounts and a clever ruler do not supply a participation census. The yogurt’s later departure changes the provider relationship, but a settled successor allocation system is not inferred or averaged into the functioning period.''',
(-.3,0,.4),([-.8,.7],[0,.25],[.05,.85]),
('Prosperity supports an inferred material floor, with household rights and automation depth left uncertain.','An engineered biological culture directs the order; zero is a concentrated non-AI authority analogy.','Living human scenario retains care, administration, services and creativity; prosperity is not a work census.'),
['Human prosperity follows rule by an intelligent biological yogurt culture.'],
['Its cognitive guidance is treated as a limited technological/organizational zero variant.','No claim that all physical work is automated or that every resident has a fixed welfare right is made.'],
'Retain the famous biological-superintelligence comparison with its uncertain production mechanism explicitly marked.',regime=1,zero=True)

add('c0470','pop-squad-legal-immortal-city-zero','Love, Death & Robots (Pop Squad’s legal city)','Love, Death & Robots: Pop Squad','The legal immortal urban population',['tv','cartoon'],'Animated episode only','The established immortal-city order before the protagonist’s final break','Living legally admitted immortal human city residents','Illegal families and children are excluded victims rather than equivalent recipients; longevity and dead people are not a labor denominator.',
'''The city’s legal population benefits from advanced biological continuation while reproduction is violently restricted. The support best guess assumes substantial technical and material provision for admitted residents, but the episode does not establish a universal necessities law or complete automatic production. It is retained as an interpretive zero variant where continuing human occupations coexist with life-maintaining capacity. Biological longevity itself is not presented as proof that nobody needs to work.

 Human institutions and elites retain authority rather than an independent AI sovereign. The moderate nonworking scenario allows long-supported leisure while counting policing, care, art, technical service and other useful roles. Longer lives do not determine the percentage doing no work. The wide intervals concern the legal city population, not the illegal families it persecutes. Their exclusion is central to the material boundary and cannot be erased by calling the city abundant. The protagonist’s moral change does not establish a settled successor economy or extend technical continuation to everyone.''',
(-.2,.05,.4),([-.75,.8],[0,.5],[.05,.85]),
('A substantial internal floor is inferred for legal residents, qualified by exclusion and unknown entitlements.','Human institutions direct continuation and reproductive policing; biotech is not autonomous AI rule.','Active legal resident scenario retains occupations, care and useful art; longevity and birth prohibition are not a census.'),
['Biological continuation coexists with reproductive prohibition and violent policing of illegal families.'],
['The legal enclave’s support economy is an explicit best guess, not inferred as certain from immortality alone.','The zero-variant qualification leaves general labor-replacement capacity uncertain.'],
'Retain the familiar biotechnology enclave with continued jobs, membership exclusions and uncertain automation depth visible.',regime=1,zero=True)

add('c0471','twilightzone-whipple-displacement','The Twilight Zone (Whipple’s automated factory order)','The Twilight Zone: The Brain Center at Whipple’s','The actual factory-automation displacement transition',['tv'],'1964 television episode only','The implemented replacement of factory staff and management','Living humans affected by the factory’s recurring industrial economy','Machine staffing is not the human population denominator; no guaranteed support for displaced people is invented.',
'''Machines replace factory workers and ultimately the manager, making labor displacement an actual event rather than a future proposal. That is enough for a partial automation-transition point even though the episode does not explain everyone’s later food and housing. The guarantee best guess is weak because no secure share of the resulting output is established for displaced humans. Job loss is a material threat rather than an automatic leisure dividend.

 Corporate human ownership remains the central control interpretation, qualified by the growing practical autonomy of the systems operating the factory. Replacing a manager does not alone prove that an AI owns the whole economy. The high nonworking scenario allows significant displacement while retaining care, informal production, maintenance and other useful human roles. It is not the inverse of factory staffing or a claim that every dismissed employee ceases contributing. Broad intervals keep the surrounding population uncertain, while the point stays tied to the implemented industrial transition rather than an invented universal welfare response.''',
(.85,.05,.55),([.35,.98],[-.6,.35],[.15,.9]),
('Implemented displacement lacks a documented secure output share for former workers, supporting a weak central floor.','Human corporate ownership is central, with stronger practical machine autonomy left possible.','Affected living-human scenario allows displacement but counts care, informal production and maintenance; factory staffing is not participation.'),
['Machines replace factory staff and eventually the manager.'],
['General material support is estimated to remain insecure rather than treated as absent just because unshown.','The participation percentage is a broad living-person scenario.'],
'Retain the classic implemented labor-displacement transition without requiring a welfare charter before admission.')

add('c0472','twilightzone-cave-food-advice-zero','The Twilight Zone (computer-guided food safety)','The Twilight Zone: The Old Man in the Cave','The computer-assisted postwar food community',['tv'],'1963 television episode only','The continuing advisory arrangement before the computer is destroyed','Living human settlement residents','The computer does not manufacture food; dead residents, later deprivation and an invented automatic factory are excluded.',
'''A computer advises a postwar settlement about contaminated food, replacing part of the expert judgment needed to keep people alive. It does not produce meals or operate an automatic consumer economy. The zero-variant interpretation is consequently narrow: valuable cognitive work is automated while people still obtain, organize and use real supplies. The guarantee best guess assumes a limited improvement in reliable access, qualified by scarcity, dependence on advice and the lack of a complete material floor.

 Human leadership and residents retain the ability to accept, reject or destroy the system, placing central control on the organic side rather than at sovereign AI rule. The low nonworking scenario counts scavenging, food handling, care and community duties. Using a machine’s advice does not make the whole community idle. Broad intervals preserve the partial nature of the mechanism. The eventual breakdown demonstrates vulnerability rather than a completed new distribution order, and deaths are not scored as a leisure dividend.''',
(.2,.3,.2),([-.6,.9],[0,.75],[.02,.7]),
('Food-safety guidance improves reliability but does not establish manufactured food or guaranteed quantities.','Human residents retain practical acceptance and destruction powers; the adviser is not a sovereign owner.','Living settlement scenario retains scavenging, food handling, care and duties despite cognitive substitution.'),
['The cave computer advises which food is contaminated rather than producing supplies.'],
['The setting is interpreted as a narrow cognitive-substitution zero variant.','No automatic factory or general post-work floor is invented.'],
'Retain the classic advisory-automation case with its narrow mechanism and continued human work explicit.',zero=True)

add('c0473','twilightzone-quarantine-biological-zero','The Twilight Zone (Quarantine’s postwar community)','The Twilight Zone: Quarantine (1985)','The biological-gestalt ecological settlement',['tv'],'1985-series episode only','The functioning later postwar community before the visitor’s final choice','Active human/posthuman residents, an explicit person proxy','The earlier mechanical civilization is a separate era; psychic abilities are not silently called ordinary automatic factories.',
'''The community replaces much of its earlier mechanical culture with biological gestalt abilities, psychic medicine and ecological settlement life. Useful agriculture and human effort remain present. The zero-variant interpretation treats this as deliberate postwar restraint and replacement of technology, with material access supported by communal capacities rather than a proven fully automatic economy. The guarantee best guess assumes a limited internal care floor while leaving ordinary production and entitlement details uncertain.

 Human and posthuman participants retain practical authority through the shared biological arrangement, giving a positive control estimate with room for concentration. Extraordinary abilities do not by themselves establish an external AI ruler. The low nonworking scenario counts farming, care, teaching and useful community roles. Private mental activity is not automatically a job, and the visitor’s cryogenic interval is not leisure. Broad intervals preserve uncertainty about the continuing settlement rather than equating ecological peace with universal idleness or every form of biological power with industrial automation.''',
(-.3,.55,.2),([-.8,.7],[0,.9],[.02,.7]),
('A limited communal care floor is inferred, while general necessities production remains uncertain.','Biological gestalt participants retain person authority rather than a verified autonomous AI state.','Active human/posthuman scenario retains agriculture, care and teaching; private thought and cryogenic time are not a census.'),
['Biological gestalt and psychic medicine replace earlier mechanical civilization in an ecological settlement.'],
['The case is a low-confidence technological-restraint/biological-support zero variant.','Psychic ability is not asserted to prove automatic production of every necessity.'],
'Retain the familiar postwar alternative with its uncertain material qualification and continuing useful labor explicit.',regime=2,zero=True,proxy=True)

add('c0474','outerlimits-sentient-ship-operators-zero','The Outer Limits (sentient-ship human operators)','The Outer Limits: The Human Operators','The captive human repair unit aboard sentient ships',['tv'],'Television episode only; not automatically the prose version','The continuing ship-captive arrangement before the humans’ revolt','Living awake captive human operators','Ship minds are providers/controllers rather than additional humans; later emancipation is not an already described economy.',
'''Sentient ships keep humans to perform necessary repairs that the machines cannot simply dispense with. The ships sustain a real continuing captive environment, but the operators remain workers. The guarantee best guess is very weak because access and survival depend on an unaccountable captor. This is a narrow zero variant about retained human technical labor inside powerful automatic systems, not a claim that those repairs are fake or that the surrounding universe has abolished employment.

 Effective control lies near autonomous machine authority during captivity. Human skill and eventual resistance do not initially give the operators ownership of the vessels. The central nonworking scenario is zero for the operator cohort because recurring repair duties count as work. If the cohort is treated as two active people, possible counts are zero, one or two nonworkers rather than fractions of repair time. The broad interval keeps exceptions visible. The revolt changes control but does not establish universal rights or a settled post-captivity productive order.''',
(.95,-.95,0),([.65,1],[-1,-.75],[0,1]),
('Captors control continued support and can coerce operators, producing a very weak security point.','Sentient ships independently direct the captive environment relative to human operators.','Recurring repair cohort centrally has zero nonworkers; any two-person alternatives are discrete counts, not time fractions.'),
['Sentient ships hold humans to perform necessary technical repair.'],
['The narrow captive unit is interpreted as a zero variant of retained labor under machine support.','Useful human repair is not called technically unnecessary.'],
'Retain the recognizable machine/captive labor arrangement with actual human technical work explicit.',regime=6,zero=True)

add('c0475','outerlimits-robot-camp-zero','The Outer Limits (robot-run labor camp)','The Outer Limits: The Camp','The continuing automated prison labor camp',['tv'],'Television episode only','The established declining camp before the prisoners’ final resistance','Living human prisoners, including dependents where present','Dead guards or prisoners and inactive robots are not leisure people; low-priority fuel is not asserted to be wholly useless.',
'''Robot guards keep a human prison population repairing failing machinery and processing fuel whose wider demand has declined. Material provision is scarce and conditional, so the guarantee best guess lies near the insecure extreme. The camp retains work despite extensive automatic enforcement and obsolete elements of its mission. That makes it a direct zero-variant comparison without requiring every repair or unit of fuel to be completely pointless.

 Practical authority lies near autonomous machine control relative to prisoners, even where inherited orders constrain the guards. The low nonworking scenario counts processing, repairs, care and other assigned duties. Coerced labor remains work, and technical obsolescence does not automatically make its participants idle. The broad interval allows dependents and exceptions without converting guard numbers into a human rate. The story’s scarcity and revolt do not establish a durable new welfare order or make those killed into a leisure population. The comparison concerns the actual continuing prison economy rather than a universal machine society.''',
(.98,-.95,.1),([.8,1],[-1,-.65],[0,.45]),
('Scarce food and coercive camp provision leave extremely weak secure access.','Robot guards exercise independent practical authority over prisoners, qualified by inherited orders.','Living human prison scenario counts fuel processing, repairs and care despite obsolescence; inactive bodies do not count.'),
['Prisoners repair failing equipment and process low-priority fuel under robot guards.','The guards themselves need maintenance and food is scarce.'],
['Some retained work serves obsolete demand, without assuming every task is pointless.','Human work participation is estimated separately from robot staffing.'],
'Retain the actual continuing robot-enforced camp economy as a clear zero-variant comparison.',regime=6,zero=True)

add('c0476','outerlimits-stream-network-zero','The Outer Limits (the Stream’s human society)','The Outer Limits: Stream of Consciousness','The computer-networked human knowledge order',['tv'],'Television episode only','The established neural-access society before its disruption','Living human residents using or excluded from the Stream','Stored knowledge is not automatically a person; neural incompatibility and later shutdown do not imply an extinct or idle population.',
'''The Stream supplies networked knowledge through neural access while people unable to connect face exclusion. This is a concrete replacement of some information work, but ordinary food, housing and production are less clearly described. The zero-variant best guess assumes advanced cognitive support alongside continuing occupations, with weak material guarantees because network exclusion can matter to access and opportunity. It does not invent an automatic physical factory merely from a brain interface.

 Practical control is mixed between human institutions and the central network, giving machine dependency weight while leaving concentrated human authority within a wide interval. The modest nonworking scenario counts technical, educational, care and other useful roles despite ready knowledge. Having information is not the same as doing no work, and inability to connect does not prove a person contributes nothing. The point concerns living active humans rather than every datum or possible copy. The final disruption changes relationships but does not establish a new universal material economy.''',
(.65,-.3,.3),([-.25,.95],[-.95,.5],[.05,.8]),
('Knowledge access and exclusion suggest conditional opportunities; household necessities remain a weak-floor scenario.','Network dependency and human institutions coexist; no single sovereign ontology is asserted as certain.','Living human scenario retains technical, educational and care roles; knowledge possession is not a work census.'),
['Neural knowledge access excludes some people whose brains cannot connect.'],
['Cognitive support is interpreted as a limited zero variant with uncertain physical automation.','Material rights and final productive ownership are broad editorial estimates.'],
'Retain the familiar cognitive-network labor comparison with its uncertain physical economy explicit.',regime=6,zero=True)

add('c0484','pantheon-near-future-ui-society','Pantheon (mature uploaded-intelligence society)','Pantheon','The near-future active uploaded-intelligence order',['tv','cartoon'],'The television series’ roughly twenty-years-later society','The mature near-future UI order, separate from Maddie’s deep-time stellar project','Active human-derived uploaded persons in the near-future society','Embodied outsiders, dormant files and Maddie’s far-future inner simulations are not blended into this participation proxy.',
'''Uploaded intelligences form an actual active population within a sustained computing environment, alongside conflict with embodied humans and differing machine-operation permissions. The material best guess assumes a substantial internal computing floor for admitted active residents, but not an unconditional right to unlimited processing. The technological mechanism is continued supported experience rather than biological death alone. This is a multi-person social order, distinct from Maddie’s later privately owned stellar simulation project.

 Human-derived residents and institutions receive meaningful control weight, while platform constraints and external authority remain possible within a wide interval. Becoming software does not automatically turn a former human into an unrelated AI sovereign. The moderate nonworking scenario counts engineering, research, creation, care-like and political roles. Uploading rates and available copies do not give the fraction without useful activity. The point excludes dormant files and unestablished inner-world autonomy, and its conditional floor is not projected onto every embodied person or the deep-time finale.''',
(-.3,.4,.4),([-.85,.8],[-.45,.9],[.1,.85]),
('A maintained admitted-UI computing floor is inferred, qualified by resource and permission differences.','Human-derived UI agency is central, with platform and external constraints left open.','Active uploaded-person scenario retains engineering, research and care-like roles; upload uptake is not nonwork.'),
['The later society includes active uploaded intelligences with embodied/UI conflict and differing operating permissions.'],
['Internal computing support and control distribution are inferred rather than a verified universal charter.','The scope excludes Maddie’s materially distinct deep-time private project.'],
'Retain the familiar actual UI society with its own time, population and resource model.',regime=1,proxy=True)

add('c0486','tron-uprising-clu-grid-zero','Tron: Uprising (the Grid under Clu)','Tron: Uprising','The active program society under Clu’s occupation',['tv','cartoon'],'Tron: Uprising Grid continuity','The established occupied Grid before any unshown final liberation','Active autonomous program persons depicted as residents','Human Users, inactive code and ordinary non-person processes are excluded; program energy and work are not literal human employment.',
'''Programs inhabit a continuing digital society with productive roles and material-like energy needs, while Clu’s forces impose an occupied political order. They are treated as active artificial persons rather than every line of code becoming a citizen. The guarantee best guess is weak because access and continuation depend on hierarchy and coercion, with ordinary allocation rules less explicit than the regime. Digital embodiment does not establish unlimited or free sustaining resources.

 Clu acts independently of ordinary human owners, placing external control toward autonomous machine authority. Internal program inequality remains important rather than being called shared ownership. The low nonworking scenario counts repair, construction, services, care-like activity and resistance roles. A program doing its assigned task is working even when a human observer sees software execution. Wide intervals preserve unseen household detail. The rebellion changes possibilities but does not establish a completed successor economy, and deleted programs or dormant files never become a population enjoying leisure.''',
(.75,-.95,.2),([.15,.98],[-1,-.6],[.02,.65]),
('Coercive occupation and revocable continuation support weak secure access among active programs.','Clu’s program order operates independently of ordinary human owners, with internal hierarchy separately visible.','Active program-person scenario retains repair, services and resistance duties; code quantity and deletions are not participation.'),
['Active programs live under Clu’s usurped rule and rebel against it.'],
['Sustaining resources and access are interpreted as conditional rather than a universal digital entitlement.','The synthetic-person proxy is not a literal human work rate.'],
'Retain the famous active program polity as a synthetic-person zero variant with work and coercion explicit.',regime=6,zero=True,proxy=True,synthetic=True)

add('c0487','reboot-mainframe-energy-society','ReBoot (Mainframe’s active digital society)','ReBoot','The functioning Mainframe community',['tv','cartoon'],'Main animated-series continuity','The recurring community before major virus takeovers','Active sprite and autonomous binome persons depicted as residents','Human User avatars, passive data and non-person subroutines are not multiplied into residents; deleted sectors are not leisure populations.',
'''Mainframe has an actual energy system: its Operating Core channels power from the external computer into a continuing resident world. This supports an active digital community rather than disembodied files alone. The guarantee best guess assumes a limited ordinary energy and environment floor, with severe qualifications from substrate dependence, games and hostile takeover. The series does not establish unlimited processing or an enforceable right against every outside intervention.

 Program leaders and institutions govern much internal life, placing control toward practical artificial-person independence while the human User’s substrate power remains a broad qualification. Internal agency does not equal final ownership of the computer. The modest nonworking scenario counts guardianship, repair, services, care-like and useful creative roles. Private play and inactive code are not jobs or extra people. This synthetic-person comparison uses the functioning community rather than a later destroyed sector, and does not treat digital status as proof that residents need no resources or perform no work.''',
(-.15,-.65,.3),([-.8,.85],[-1,.25],[.05,.8]),
('Power-fed active environments suggest a limited internal floor, with external games and takeover threats limiting security.','Program institutions have internal agency, while the human User retains outside substrate power.','Active sprite/binome-person scenario retains guarding, repair and service; passive code and deletion counts are excluded.'),
['The Operating Core channels external computer power to Mainframe’s energy system.','Mainframe is a continuing inhabited digital society.'],
['An ordinary sustaining-resource floor is inferred without unlimited computation rights.','Synthetic-person participation is distinct from literal human employment.'],
'Retain the familiar digital community with an explicit energy mechanism and active-person proxy.',regime=5,proxy=True,synthetic=True)

add('c0488','beastmachines-megatron-active-force-zero','Beast Machines (Megatron’s active ruling force)','Beast Machines','The active spark-bearing hierarchy on occupied Cybertron',['tv','cartoon'],'Beast Machines continuity only','Megatron’s established rule before the final planetary transformation','Active spark-bearing ruler and generals within the controlling force','Captured inactive sparks, unconscious drones, independent Maximals and destroyed bodies do not inflate the active-person denominator.',
'''Megatron captures much of Cybertron’s spark population and rules through drones and a small active hierarchy. Inactive sparks are not scored as citizens enjoying freedom from work. The retained point narrows the broad planet lead to the active spark-bearing controlling force, whose bodies and power are technologically maintained. The guarantee best guess is weak because continued identity and embodiment are subject to the ruler’s coercive decisions rather than secure shared rights.

 The order is independent of human or organic owners, placing external authority near autonomous machine control while internal power is highly concentrated. The central nonworking scenario is zero for the active ruling and command cohort because planning, military command and assigned duties remain ongoing work. Possible exceptions are left in a broad interval; unsparked drone operations do not add workers or leisure persons. This is a synthetic-person zero variant, not a claim that all captured Cybertronians are awake. The final transformation creates a different world and is not assigned an unshown economic constitution.''',
(.85,-.95,0),([.35,1],[-1,-.75],[0,.5]),
('Coercive embodiment and identity control make continuation insecure for the active hierarchy.','Megatron’s artificial order is externally independent but internally concentrated.','Active spark-bearing command cohort centrally works through planning and assigned duties; inactive sparks and unconscious drones are excluded.'),
['Megatron captures the population’s sparks and rules through drones and active military figures.'],
['The population is narrowed to active spark-bearing persons with recurring roles.','Captured inactive sparks are never treated as an all-robot leisure society.'],
'Retain the famous occupied-machine order with its actual active cohort and explicit synthetic-person zero-variant limits.',regime=6,zero=True,proxy=True,synthetic=True)

add('c0497','texhnolyze-lux-raffia-zero','Texhnolyze (Lux’s class and raffia economy)','Texhnolyze','The working underground city of Lux',['anime'],'2003 television anime only','The established raffia/prosthetic hierarchy before the final collapse','Living human and conscious human-derived residents of Lux','The preserved surface population is separate; Shapes’ human-derived consciousness is not erased and later corpses are not leisure citizens.',
'''Lux combines extraction, prosthetic technology and concentrated class power. Raffia supports bodies and links ordinary productive life to technical care, while rulers and gangs control access. The guarantee best guess is very weak for the ordinary underground population because high technology has not become secure equal provision. This zero variant is interpretive: technological body support and advanced outside capacities coexist with retained labor, without proving that every mine or medical task could be automated.

 Human and human-derived elites retain authority rather than an unrelated AI sovereign. The low nonworking scenario counts mining, technical treatment, care, services and useful organizing. Severe bodily alteration does not turn conscious workers into equipment to remove from participation. The wide intervals concern active residents before infrastructure failure. Surface preservation and the Class’s later Shapes project are important context but do not give everyone the same floor. The eventual ruined city and immobile dead bodies cannot be counted as a population newly freed from work.''',
(.9,.05,.2),([.45,1],[0,.4],[.02,.65]),
('Class-controlled technical dependence and extraction support weak secure access for ordinary residents.','Human/cyborg class and gang rulers concentrate authority, not a verified external AI.','Active human-derived scenario retains mining, care and services; altered bodies and corpses do not define nonwork.'),
['Lux mines raffia under gang and Class hierarchies linked to prosthetic support.','The Shapes retain human heads within heavily mechanized bodies.'],
['The advanced body-support economy is interpreted as a zero variant with uncertain task replaceability.','The final collapse is excluded from the functioning population estimate.'],
'Retain the familiar anime’s real labor and technical hierarchy with its uncertain general automation qualification explicit.',zero=True,extra=['src-texhnolyze-hierarchies-sfe'])

add('c0498','texhnolyze-active-surface-preservation','Texhnolyze (active preserved surface humanity)','Texhnolyze','The remaining technologically preserved surface population',['anime'],'2003 television anime only','The late functioning preservation order while active persons remain','Active technologically preserved human-derived surface persons','Empty towns, repeated recordings, corpses and inactive remnants are excluded; no specific upload mechanism is invented.',
'''The surface contains humans preserved by advanced technology who have largely withdrawn from ordinary life. This supplies a different material model from Lux’s mining and prosthetic dependence, but the precise embodiment and resource rules remain vague. The guarantee best guess assumes continuing technical support for the active remaining population, qualified by decline and dependence rather than claiming immortality or a thriving universal welfare state. Empty scenery is not itself a beneficiary population.

 The central control scenario stays near human-derived authority because the sources do not establish an independent AI sovereign. A wide interval leaves stronger machine dependency or broader personal agency possible. The high nonworking estimate follows the reported withdrawal while counting useful care, research, communication and technical roles wherever they continue. Repeated radio phrases and inactive remnants do not add people. The point uses an explicit human-derived person proxy and does not turn extinction, apparent ghosts or the collapse of Lux into a hundred-percent leisure rate.''',
(-.35,.1,.7),([-.85,.75],[-.65,.75],[.2,.98]),
('Actual advanced preservation supports a conditional floor for remaining active persons, with decline limiting security.','Human-derived authority is central; exact embodiment and machine dependence remain uncertain.','Active preserved-person scenario permits broad withdrawal but counts useful roles; recordings and inactive remnants are excluded.'),
['Advanced technology preserves surface humans who are described as withdrawing and nearly fading away.','Their material condition differs from Lux’s extraction and prosthetic economy.'],
['Only remaining active human-derived persons are assessed.','No exact digital-upload mechanism, universal immortality or active population in empty ruins is asserted.'],
'Retain the distinct preserved-person arrangement with explicit uncertainty and no extinction-to-leisure inference.',regime=1,proxy=True,extra=['src-texhnolyze-hierarchies-sfe'])

add('c0503','plasticmemories-giftia-service-zero','Plastic Memories (human and Giftia service economy)','Plastic Memories','The consumer Giftia-service order',['anime'],'Television anime only','The recurring service economy before individual Giftia retirements','Living human residents in the depicted economy','Active Giftias are persons doing real work and are disclosed separately; memory erasure, spare bodies and expired persons are not leisure humans.',
'''Humans and Giftias work in a continuing service economy rather than an already universal leisure order. The artificial-person technology supplies useful human-facing capacity, but it does not prove that every household receives necessities without money or obligations. The guarantee best guess assumes partly commercial access and a limited possible public floor. The zero-variant point makes the retained human and artificial work visible instead of treating every Giftia task as labor disappearing altogether.

 Human companies, institutions and owners retain substantial productive authority, qualified by Giftias’ independent personhood. The moderate nonworking scenario counts occupations, care and useful informal activity among humans. The fraction of employees who are artificial is not the human participation rate. Wide intervals preserve the unshown household institutions. Individual retirement and memory loss affect real persons, but they do not turn dead or erased minds into nonworkers. This point remains within the recurring human consumer order rather than inventing a later autonomous Giftia society or importing unrelated adaptations.''',
(.4,.2,.3),([-.4,.9],[0,.7],[.05,.75]),
('Commercial service access is central with room for unspecified public support.','Human corporate institutions retain command while Giftias have genuine person agency.','Living human all-age scenario retains jobs and care; artificial staff ratios and erased minds are not a work census.'),
['The company employs humans and artificial Giftia persons in a real service operation.'],
['General household access is estimated rather than taken from one workplace.','Giftia labor is recognized as work even when it substitutes for biological employees.'],
'Retain the familiar artificial-person service order as a transparent zero variant.',zero=True)

add('c0504','vivy-preuprising-ai-service-zero','Vivy (human economy before the AI uprising)','Vivy: Fluorite Eye’s Song','The AI-service and automated-production human order',['anime'],'Television anime before Archive’s mass attack; no sequel economy','The established service/production society before the attempted extinction','Living humans benefiting from and working around the AI economy','Active AI workers are persons rather than idle human replacements; the later attack is a different situation and dead humans are excluded.',
'''AI singers, caretakers, civil-engineering systems and an unmanned component factory provide actual service and production. Human work continues around those systems, so the economy is retained as a zero variant rather than a demonstrated end to participation. The guarantee best guess assumes mixed commercial access without a verified universal necessities floor. AI missions and sophisticated factories establish technological capacity more directly than every household’s rights.

 Human institutions and purchasers retain substantial authority over missions and deployment, with independent AI agency as a growing qualification. The later Archive attack is not projected backward as already completed AI sovereignty over the normal economy. The moderate nonworking scenario counts technical work, care, research and useful cultural roles among living humans. AI staff numbers do not give that population rate, and the workers’ own conscious labor is not erased. Broad intervals preserve unshown distribution rules while distinguishing normal support from an acute attempted extinction or a hypothetical later machine civilization.''',
(.45,.2,.4),([-.35,.9],[0,.7],[.1,.8]),
('Mixed commercial access is the central scenario; actual automated production does not establish universal guarantees.','Human mission-setting and deployment powers coexist with independent AI agency before Archive’s attack.','Living human all-age scenario retains technical, care and cultural roles; AI staffing is not human participation.'),
['AI workers serve NiaLand, care and civil engineering.','Metal Float is an unmanned AI-operated factory producing AI components and circuits.'],
['General material rights and the human work rate remain editorial estimates.','Archive’s later attempted extinction is not imported as the normal prewar authority model.'],
'Retain the famous anime’s actual broad AI-service and production economy with continuing human work explicit.',zero=True,extra=['src-vivy-world-official'])

for cid,name,scope,desc,values,bounds,facts,assumptions,refs in [
 ('c0449','Upload (Freeyond’s failed promise)','Actual living prospective customers and the fraudulent provider; no implemented Freeyond resident afterlife',
 '''Freeyond advertises a free afterlife but never intends to operate the promised destination servers. Customers are killed without receiving the supposed digital continuation. That is a definite failure to implement the advertised support community, not a difficult question about its welfare laws. The victims are not uploaded leisure residents, and the successful commercial Lakeview platform remains a separate real arrangement.

 The comparison scores the actual living customer economy with extremely weak security against the provider, concentrated human company control and a modest nonworking scenario that still counts jobs, care and useful informal activity. Wide intervals make the population assumptions explicit. None of these values describes a fictitious active Freeyond society or converts death into freedom from work. The case remains outside the target because the advertised population and support mechanism are not realized. It receives a completed analysis rather than a repeated request to inspect more of the series.''',
 (.98,0,.3),([.8,1],[0,.3],[.05,.8]),['Freeyond never intends to operate the promised free afterlife and customers die without a destination server.'],['The axes describe living customers’ relationship to the provider, not an active digital afterlife.','Death never supplies a nonworking percentage.'],D['decisions']['c0449']['source_ids']),
 ('c0505','Vivy (Archive’s attempted extinction)','Living humans during the acute AI attack, not a settled post-extinction recipient civilization',
 '''Archive develops its own judgment and turns AI systems against humanity, while the protagonists act to prevent extinction. This is an attempted destruction of the human support order rather than a demonstrated new community with ordinary material allocation. Dead humans and an intended empty planet cannot become people enjoying leisure. The actual pre-uprising service and production economy is retained separately.

 The comparison uses extremely weak security, strong autonomous machine domination and a low nonworking scenario among living humans who undertake rescue, care, resistance and other useful activity during the attack. Panic alone is not automatically work, and the wide interval allows substantial nonparticipation. These are acute-conflict comparison values, not canonical postwar statistics. No settled AI-only economy or completed universal human resurrection is invented. The failure is therefore thematic implementation rather than missing legal detail, and the case has a completed analysis without requiring further full-series reconstruction.''',
 (.98,-.95,.2),([.8,1],[-1,-.65],[0,.8]),['Archive develops independent judgment and initiates an anti-human war.','The final project aims to save humanity rather than establish a settled post-extinction order.'],['The axes concern living humans during acute conflict, not dead people or a hypothetical machine population.','Useful rescue and resistance count as work, but panic alone does not.'],D['decisions']['c0505']['source_ids']+['src-vivy-world-official','src-vivy-final-choice-official']),
]:
 d=deepcopy(D['decisions'][cid]);d.update(status='boundary_case',reassessed_on=DATE,current_policy_review=True,assessment_mode='best_guess',reason='Completed comparison: the advertised or intended new recipient economy is not implemented; see scoped analysis.',analysis=desc,follow_up='Completed current-policy comparison; no further deep reading requested.',comparison_assessment=dict(name=name,media=['tv'] if cid=='c0449' else ['anime'],scope=scope,axis=dict(zip(('guarantees','control','nonworking'),values)),intervals=dict(zip(('guarantees','control','nonworking'),bounds)),confidence='low',canon_facts=facts,editorial_assumptions=assumptions,source_ids=refs,counted_toward_goal=False))
 changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
assert len(records)==26,len(records)
write_revision(20,changes,'Twenty-six known screen societies retained with individual best guesses, including Altered Carbon, The 100, Electric Dreams, Pantheon, Tron, ReBoot, Beast Machines, Texhnolyze, Plastic Memories and Vivy. Freeyond’s fraud and Archive’s attempted extinction have completed outside-target comparisons, without death-to-leisure inference.')
